{"cards": [{"node_code": "N_79af31ed02dd579b", "definition": "研究公路运输中车站、客运站、货运站及枢纽的布局规划、功能分区、设施配置、作业流程及运营管理的技术与管理内容。", "boundary": "本节点聚焦于“节点”层面的运营组织，即车辆与客货在停留、中转、集散时的空间组织与流程管理。边界在于区分“线路”层面的行车组织（归入行车组织）与“节点”层面的站场作业。若内容涉及站房建筑结构或道路工程设计，归入道路工程；若涉及站场内的交通信号控制，归入交通工程。", "includes": ["客运站、货运站及综合枢纽的布局与功能设计", "站场内的车辆调度、客货装卸及中转作业流程", "枢纽运营管理与服务设施配置"], "excludes": ["站房及场地的土建结构设计与施工（归入道路工程）", "站场内部交通信号控制与路网通行管理（归入交通工程与交通管理）"], "sibling_distinctions": [{"other_code": "N_233746aee3bc7b68", "rule": "本节点侧重“点”（车站/枢纽）的静态布局与节点内作业；行车组织侧重“线”（线路/区间）的动态运行与车辆调度。"}, {"other_code": "N_67a9b1cc28a3a542", "rule": "本节点侧重站场内的物理作业与空间组织；货物运输及商务工作侧重货物流转的商务流程、单证及合同管理。"}], "cross_boundary_rule": "若内容涉及“枢纽交通组织”，侧重站场内部车辆流线归本节点；侧重枢纽与外部路网的衔接信号控制，可关联交通工程。"}, {"node_code": "N_233746aee3bc7b68", "definition": "研究公路运输中车辆在线路上的运行组织、行车计划编制、调度指挥、运行图制定及行车安全规则的技术与管理内容。", "boundary": "本节点聚焦于“动态运行”层面的组织技术，即车辆如何在路网上高效、安全地移动。边界在于区分“静态节点”作业（归入车站及枢纽）与“动态线路”运行。若内容涉及车辆机械性能对行车的影响，归入汽车工程；若涉及行车调度系统的软件算法，归入电子计算机应用。", "includes": ["行车计划、运行图及调度指挥技术", "车辆在线路上的运行组织与间隔控制", "行车安全规则、事故预防及运行监测"], "excludes": ["车站及枢纽内的静态作业与布局（归入车站及枢纽）", "行车调度系统的底层算法与软件架构（归入电子计算机应用）"], "sibling_distinctions": [{"other_code": "N_79af31ed02dd579b", "rule": "本节点侧重“线”（线路/区间）的动态运行与调度；车站及枢纽侧重“点”（站场）的静态布局与节点内作业。"}, {"other_code": "N_67a9b1cc28a3a542", "rule": "本节点侧重车辆运行的技术组织与调度；货物运输及商务工作侧重货运的商务流程、单证及合同管理。"}], "cross_boundary_rule": "若内容涉及“智能调度”，侧重调度规则与运行组织归本节点；侧重调度算法、数据处理或系统架构，可关联电子计算机应用。"}, {"node_code": "N_67a9b1cc28a3a542", "definition": "研究公路货物运输的组织技术、业务流程、单证管理、合同订立、费用结算及货运代理等商务工作的内容。", "boundary": "本节点聚焦于“货运”领域的业务与商务流程，包括从托运、承运、交付到结算的全过程。边界在于区分“客运”业务（归入旅客运输）与“货运”业务。若内容涉及货运车辆的技术性能，归入汽车工程；若涉及货运成本与运价制定，归入陆路、公路运输经济。", "includes": ["货物运输组织、托运、承运及交付流程", "货运单证、合同管理、费用结算及保险", "货运代理、多式联运商务及特殊货物运输业务"], "excludes": ["旅客运输业务与流程（归入旅客运输）", "货运成本分析、运价制定及市场规律（归入陆路、公路运输经济）"], "sibling_distinctions": [{"other_code": "N_8b46868b711d9463", "rule": "本节点侧重“货物”的运输业务与商务流程；旅客运输侧重“旅客”的运输服务、票务及客运组织。"}, {"other_code": "N_233746aee3bc7b68", "rule": "本节点侧重货运的商务流程、单证及合同管理；行车组织侧重车辆在线路上的动态运行与调度技术。"}], "cross_boundary_rule": "若内容涉及“货运信息系统”，侧重业务流程与单证管理归本节点；侧重系统架构、算法或数据处理，可关联电子计算机应用。"}]}
